interface Props { billing: 'monthly' | 'annual'; onBillingChange: (b: 'monthly' | 'annual') => void; }

export function PricingHero({ billing, onBillingChange }: Props) {
  return (
    <section className="text-center py-20 px-4 bg-gradient-to-b from-indigo-50/60 to-white">
      <span className="inline-block px-3 py-1 text-xs font-semibold text-indigo-700 bg-indigo-100 rounded-full mb-4">Simple, transparent pricing</span>
      <h1 className="text-4xl md:text-5xl font-extrabold text-gray-900 leading-tight">
        Plans for teams of all sizes
      </h1>
      <p className="mt-4 text-lg text-gray-500 max-w-xl mx-auto">
        Start free, scale as you grow. No hidden fees, no surprises.
      </p>
      {/* Billing toggle */}
      <div className="mt-8 inline-flex items-center gap-3 bg-gray-100 p-1 rounded-xl">
        <button onClick={() => onBillingChange('monthly')}
          className={`px-5 py-2 rounded-lg text-sm font-semibold transition-all ${billing === 'monthly' ? 'bg-white shadow text-gray-900' : 'text-gray-500 hover:text-gray-700'}`}>
          Monthly
        </button>
        <button onClick={() => onBillingChange('annual')}
          className={`px-5 py-2 rounded-lg text-sm font-semibold transition-all ${billing === 'annual' ? 'bg-white shadow text-gray-900' : 'text-gray-500 hover:text-gray-700'}`}>
          Annual <span className="text-emerald-600 text-xs font-bold ml-1">−20%</span>
        </button>
      </div>
    </section>
  );
}

