    description: 'Perfect for side projects and experiments.',
    cta: 'Get started free',
    ctaStyle: 'border border-gray-200 text-gray-900 hover:bg-gray-50',
    features: ['3 projects', '1 GB storage', 'Community support', 'Basic analytics', 'API access'],
    highlighted: false,
  },
  {
    name: 'Pro',
    monthly: '$29',
    annual: '$23',
    description: 'Great for growing teams shipping fast.',
    cta: 'Start free trial',
    ctaStyle: 'bg-indigo-600 hover:bg-indigo-700 text-white',
    badge: 'Most popular',
    features: ['Unlimited projects', '50 GB storage', 'Priority support', 'Advanced analytics', 'API access', 'Custom domain', 'Team seats (5)'],
    highlighted: true,
  },
  {
