                ? 'border-indigo-500 shadow-2xl shadow-indigo-100 scale-105'
                : 'border-gray-100 shadow-md hover:shadow-lg'
            }`}
          >
            {plan.badge && (
              <div className="absolute -top-3.5 left-1/2 -translate-x-1/2">
                <span className="px-3 py-1 bg-indigo-600 text-white text-xs font-bold rounded-full whitespace-nowrap">{plan.badge}</span>
              </div>
            )}
            <div className="mb-6">
              <h3 className="text-lg font-bold text-gray-900">{plan.name}</h3>
              <p className="text-sm text-gray-500 mt-1">{plan.description}</p>
            </div>
            <div className="mb-6">
              <span className="text-4xl font-extrabold text-gray-900">{billing === 'monthly' ? plan.monthly : plan.annual}</span>
              {plan.monthly !== '$0' && <span className="text-gray-400 text-sm ml-1">/mo</span>}
              {billing === 'annual' && plan.monthly !== '$0' && (
                <p className="text-xs text-emerald-600 font-medium mt-1">Billed annually</p>
              )}
            </div>
            <ul className="space-y-3 flex-1 mb-8">
              {plan.features.map((f) => (
                <li key={f} className="flex items-center gap-2.5 text-sm text-gray-600">
                  <Check className="h-4 w-4 text-indigo-500 flex-shrink-0" />
                  {f}
                </li>
              ))}
            </ul>
            <button className={`w-full h-12 rounded-xl text-sm font-semibold transition-all ${plan.ctaStyle}`}>{plan.cta}</button>
          </div>
        ))}
      </div>
    </section>
  );
}

/components/PricingFaq.tsx.content:
"use client";
import { useState } from 'react';
import { ChevronDown } from 'lucide-react';

const FAQ = [
  { q: 'Can I switch plans later?', a: 'Yes, you can upgrade or downgrade at any time. Changes take effect at the next billing cycle.' },
  { q: 'Is there a free trial?', a: 'Pro comes with a 14-day free trial, no credit card required.' },
  { q: 'What payment methods do you accept?', a: 'We accept all major credit cards, PayPal, and wire transfers for Enterprise.' },
  { q: 'Do you offer refunds?', a: 'Yes, we offer a 30-day money-back guarantee on all paid plans.' },
];

export function PricingFaq() {
  const [open, setOpen] = useState<number | null>(null);
  return (
    <section className="max-w-2xl mx-auto px-4 pb-24">
      <h2 className="text-2xl font-bold text-gray-900 text-center mb-10">Frequently asked questions</h2>
      <div className="divide-y divide-gray-100 border border-gray-100 rounded-2xl overflow-hidden">
        {FAQ.map((item, i) => (
          <div key={i}>
            <button onClick={() => setOpen(open === i ? null : i)}
              className="w-full flex items-center justify-between px-6 py-5 text-left hover:bg-gray-50 transition-colors">
              <span className="font-medium text-gray-900 text-sm">{item.q}</span>
              <ChevronDown className={`h-4 w-4 text-gray-400 flex-shrink-0 transition-transform ml-4 ${open === i ? 'rotate-180' : ''}`} />
            </button>
            {open === i && (
              <div className="px-6 pb-5">
                <p className="text-sm text-gray-500">{item.a}</p>
              </div>
            )}
          </div>
        ))}
      </div>
    </section>
  );
}

